def run(_context:str):
 import json,os,tempfile,time
 app=core.Application.get();doc=authoring_document(app,'leg');assert doc==app.activeDocument or doc.activate();d=fusion.Design.cast(app.activeProduct);assert d.activateRootComponent();root=d.rootComponent;tick=time.monotonic();assert not any(c.partNumber=='CANDIDATE_hc_hip_hub'for c in d.allComponents);source=next(c for c in d.allComponents if c.partNumber=='CANDIDATE_sl_hip_hub').bRepBodies.item(0);o=root.occurrences.addNewComponent(core.Matrix3D.create());o.isLightBulbOn=False;c=o.component;c.name='Hip output hub with open knee-case clearance';c.partNumber='CANDIDATE_hc_hip_hub';g=IntentGeometry(d,c);intent=CohesiveLimbIntent(g)
 for name,value in {'hc_case_nominal_radius':39.25,'hc_case_rear_plane':9,'hc_case_radial_clearance':.5,'hc_case_axial_clearance':.25}.items():g.parameter(name,value,comment='Frozen RS02 case envelope and independent unqualified prototype clearances; tie-tube bearing planes remain fixed.')
 g.parameter('hc_relief_radius','hc_case_nominal_radius+hc_case_radial_clearance');g.parameter('hc_relief_start_y','hc_case_rear_plane-hc_case_axial_clearance');g.parameter('hc_relief_depth','sm_hub_pad_y+sm_hub_tie_pad_thickness-hc_relief_start_y+.25 mm');items=core.ObjectCollection.create();items.add(source);copy=c.features.copyPasteBodies.add(items);copy.name='Linked ribbed output hub and full tie lands';body=copy.bodies.item(0);sk=intent.circles('hc_relief_start_y',[('0 mm','0 mm','hc_relief_radius')],'Open rear-case clearance');body=intent.extrude_all(sk,'hc_relief_depth','Shallow case clearance preserves tube bearing footprints',fusion.FeatureOperations.CutFeatureOperation,body);body.name=c.name
 ro=root.occurrences.addNewComponent(core.Matrix3D.create());ro.isLightBulbOn=False;rc=ro.component;rc.name='Right output hub with open knee-case clearance';rc.partNumber='CANDIDATE_hc_hip_hub_right';items=core.ObjectCollection.create();items.add(body);copy=rc.features.copyPasteBodies.add(items);copy.name='Linked relieved left hub';seed=copy.bodies.item(0);items=core.ObjectCollection.create();items.add(seed);before={b.entityToken for b in rc.bRepBodies};feature=rc.features.mirrorFeatures.add(rc.features.mirrorFeatures.createInput(items,rc.xZConstructionPlane));feature.name='Right-hand final relieved hub';assert len([b for b in rc.bRepBodies if b.entityToken not in before])==1;rc.features.removeFeatures.add(seed).name='Remove unhanded construction copy';rows=[]
